"""The EPT matrix-method kernels from the tables generated by ``tools/pt_autogen``
(``tables/ept/matrix_<22|13|uv>.dat``).

A P22 block is ``R(nu1, nu2) I(nu1, nu2)``, the master integral factorizing as
``I(nu1, nu2) = g(nu1) g(nu2) h(nu1 + nu2)`` (:func:`master_g`, :func:`master_h`), and a P13 block
``R(nu1) tan(pi nu1) / pi`` (:func:`p13_matrix`).  ``R`` is stored as a constant times a product of integer
polynomial factors (positive powers in the numerator, negative in the denominator).  The factors of every P22 block
separate (:func:`p22_separable_form`): the one-variable factors pair up as ``u(nu1) u(nu2)``, and the product of the
others is a symmetric polynomial, written exactly as ``sum_b s_b(nu1 + nu2) (nu1 nu2)^b``.  Block names and the
conventions are stated in the headers of the tables.
"""
import math
import os
from functools import lru_cache
from typing import NamedTuple

import numpy as np
from numpy.polynomial import polynomial
from scipy.special import loggamma

from .table_text import fraction, records

TABLE_DIR = os.path.join(os.path.dirname(__file__), 'tables', 'ept')
N_NU = {'22': 2, '13': 1}
"""The number of variables (nu1, nu2 for 22, nu1 for 13) of the polynomial factors."""


def master_g(nu):
    """``Gamma(3/2 - nu) / Gamma(nu)``, the factor of each variable of the master integral (numpy)."""
    return np.exp(loggamma(1.5 - nu) - loggamma(nu))


def master_h(nu12):
    """``Gamma(nu12 - 3/2) / (8 pi^(3/2) Gamma(3 - nu12))``, the factor of ``nu12 = nu1 + nu2`` of the master integral
    (numpy)."""
    return np.exp(loggamma(nu12 - 1.5) - loggamma(3 - nu12) - np.log(8 * np.pi**1.5))


def _matrix_table(prefix):
    """``(names, blocks, factors)`` of tables/ept/matrix_<prefix>.dat (``_tables``)."""
    nv = N_NU[prefix]
    lines = records(os.path.join(TABLE_DIR, f'matrix_{prefix}.dat'))
    consts = {r[1]: float(fraction(r[2])) for r in lines if r[0] == 'block'}
    powers = {b: [] for b in consts}        # block -> [power of the factor f = 0, 1, ..]
    coefficients = {}                       # (block, f) -> {exponents of nu: coefficient}
    for r in lines:
        if r[0] == 'factor':
            powers[r[1]].append(int(r[3]))
        elif r[0] == 'term':
            coefficients.setdefault((r[1], int(r[2])), {})[tuple(int(e) for e in r[3:3 + nv])] = float(fraction(r[3 + nv]))
    blocks, index, factors = [], {}, []
    for b, const in consts.items():
        flist = []
        for f, power in enumerate(powers[b]):
            terms = coefficients[(b, f)]
            coeffs = np.zeros(tuple(1 + max(e[d] for e in terms) for d in range(nv)))
            for e, c in terms.items():
                coeffs[e] = c
            key = (coeffs.shape, coeffs.tobytes())
            if key not in index:          # a factor shared by several blocks is one array
                index[key] = len(factors)
                factors.append(coeffs)
            flist.append((index[key], power))
        blocks.append((const, flist))
    return tuple(consts), blocks, factors


@lru_cache(maxsize=None)
def _tables():
    """``{'22' | '13': (names, blocks, factors), 'uv': array}`` of tables/ept/matrix_<22|13|uv>.dat.

    ``blocks[i] = (const, [(factor index, power)])`` in the order f of the factors of block i;
    ``factors`` are the distinct polynomial factors (coefficient arrays ``[i, j]`` of nu1^i nu2^j,
    ``[i]`` of nu1^i for 13, without zero padding).  ``uv`` is ``(nterms, 7)``, the powers of
    (mu, f, b1, b2, bG2, bGamma3) and the coefficient of each monomial of ``Z1 Z3_UV``.
    """
    out = {prefix: _matrix_table(prefix) for prefix in ('22', '13')}
    path = os.path.join(TABLE_DIR, 'matrix_uv.dat')
    lines = records(path)
    out['uv'] = np.array([[float(int(e)) for e in r[1:7]] + [float(fraction(r[7]))] for r in lines])
    return out


def block_names(prefix):
    """Names of the blocks ``prefix`` ('22' or '13'), sorted as strings."""
    return list(_tables()[prefix][0])


def _block(prefix, name):
    """``(const, [(factor coefficients, power)])`` of block ``name``."""
    names, blocks, factors = _tables()[prefix]
    const, flist = blocks[names.index(name)]
    return const, [(factors[j], power) for j, power in flist]


def p13_matrix(name, nu):
    """``R(nu) tan(pi nu) / pi`` of the P13 block ``name`` at the numpy array ``nu``."""
    const, flist = _block('13', name)
    num, den = const, 1.0
    for coeffs, power in flist:
        value = polynomial.polyval(nu, coeffs)
        for _ in range(abs(power)):
            if power > 0:
                num = num * value
            else:
                den = den * value
    return num / den * (np.tan(np.pi * nu) / np.pi)


class SeparableForm(NamedTuple):
    """``R(nu1, nu2) = const u(nu1) u(nu2) sum_b s_b(nu1 + nu2) (nu1 nu2)^b`` of a P22 block.

    ``u`` is the product of the one-variable factors, ``((coefficients by increasing power, power), ...)`` sorted (equal
    tuples, equal u); ``s`` holds the coefficients of s_0, s_1, .. by increasing power (integers, exact).
    """

    const: float
    u: tuple
    s: tuple

    def u_at(self, nu):
        """u(nu) at the numpy array ``nu``."""
        out = np.ones_like(nu)
        for coeffs, power in self.u:
            out = out * polynomial.polyval(nu, coeffs) ** power
        return out

    def s_at(self, b, nu12):
        """s_b(nu12) at the numpy array ``nu12``."""
        return polynomial.polyval(nu12, self.s[b])


def p22_separable_form(name):
    """The :class:`SeparableForm` of the P22 block ``name`` from the factors of its table.

    The factors of one variable form u; the other factors may only multiply (a two-variable denominator does not
    separate) and their product must be symmetric.  ValueError otherwise, and if the factors in nu1 differ from those
    in nu2.
    """
    const, flist = _block('22', name)
    in_nu1, in_nu2, numerator = [], [], np.ones((1, 1))
    for coeffs, power in flist:
        if coeffs.shape[1] == 1:
            in_nu1.append((tuple(coeffs[:, 0]), power))
        elif coeffs.shape[0] == 1:
            in_nu2.append((tuple(coeffs[0]), power))
        elif power > 0:
            for _ in range(power):
                numerator = _poly_product(numerator, coeffs)  # the product of the polynomials, exact for integers
        else:
            raise ValueError(f'{name}: a two-variable factor in the denominator does not separate')
    if sorted(in_nu1) != sorted(in_nu2):
        raise ValueError(f'{name}: the one-variable factors differ between nu1 and nu2')
    return SeparableForm(const, tuple(sorted(in_nu1)), _symmetric_parts(numerator, name))


def _poly_product(a, b):
    """The coefficients ``[i, j]`` of the product of two polynomials in (nu1, nu2), exact for integers."""
    out = np.zeros((a.shape[0] + b.shape[0] - 1, a.shape[1] + b.shape[1] - 1))
    for (i, j), c in np.ndenumerate(a):
        out[i:i + b.shape[0], j:j + b.shape[1]] += c * b
    return out


def _symmetric_parts(coeffs, name):
    """``(s_0, s_1, ..)``: the polynomial ``coeffs`` (``[i, j]`` of nu1^i nu2^j) as ``sum_b s_b(nu1 + nu2) (nu1 nu2)^b``,
    each s_b by increasing power.  Exact for integer coefficients; ValueError if the polynomial is not symmetric."""
    n = max(coeffs.shape)
    rest = np.zeros((n, n))
    rest[:coeffs.shape[0], :coeffs.shape[1]] = coeffs
    parts = []
    while rest.any():
        s = rest[:, 0].copy()                  # s_b(x) = rest(x, 0)
        rest = rest - _of_sum(s)               # rest(x, 0) = 0 now
        if rest[0].any():                      # rest(0, y) = rest(0, y) - rest(y, 0) before the subtraction
            raise ValueError(f'{name}: the numerator is not symmetric in nu1 and nu2')
        parts.append(s)
        rest = rest[1:, 1:]                    # divided by nu1 nu2
    return tuple(parts)


def _of_sum(s):
    """The coefficients ``[i, j]`` of nu1^i nu2^j of ``s(nu1 + nu2)``, ``s`` by increasing power (square array)."""
    out = np.zeros((len(s), len(s)))
    for d, c in enumerate(s):
        for i in range(d + 1):
            out[i, d - i] += c * math.comb(d, i)
    return out


def uv_table():
    """``(nterms, 7)`` monomials of ``Z1 Z3_UV``: powers of (mu, f, b1, b2, bG2, bGamma3) and the
    coefficient, sorted by the powers of (mu, f, b1).

    ``Z1 = b1 + f mu^2``, ``Z3_UV = -61/315 b1 + ((-3/5 + 2/105 b1) f + (-16/35 - 1/3 b1) f^2) mu^2
    + (-46/105 f^2 - 1/3 f^3) mu^4``.
    """
    return _tables()['uv'].copy()
